     1→"use client";
     2→
     3→import { useState } from "react";
     4→import {
     5→  Table,
     6→  TableBody,
     7→  TableCell,
     8→  TableHead,
     9→  TableHeader,
    10→  TableRow,
    11→} from "@/components/ui/table";
    12→import { Input } from "@/components/ui/input";
    13→import { Button } from "@/components/ui/button";
    14→import { Checkbox } from "@/components/ui/checkbox";
    15→import { Badge } from "@/components/ui/badge";
    16→import {
    17→  Select,
    18→  SelectContent,
    19→  SelectItem,
    20→  SelectTrigger,
    21→  SelectValue,
    22→} from "@/components/ui/select";
    23→import {
    24→  Plus,
    25→  Trash2,
    26→  Download,
    27→  Upload,
    28→  RefreshCw,
    29→  MoreVertical,
    30→  Search,
    31→  Eye,
    32→  Pencil,
    33→  ArrowLeftRight,
    34→  ArrowRight,
    35→  Loader2,
    36→  AlertCircle,
    37→} from "lucide-react";
    38→import {
    39→  DropdownMenu,
    40→  DropdownMenuContent,
    41→  DropdownMenuItem,
    42→  DropdownMenuSeparator,
    43→  DropdownMenuTrigger,
    44→} from "@/components/ui/dropdown-menu";
    45→import {
    46→  AlertDialog,
    47→  AlertDialogAction,
    48→  AlertDialogCancel,
    49→  AlertDialogContent,
    50→  AlertDialogDescription,
    51→  AlertDialogFooter,
    52→  AlertDialogHeader,
    53→  AlertDialogTitle,
    54→} from "@/components/ui/alert-dialog";
    55→import { AddDictionaryDialog, EditDictionaryDialog, FileUploadDialog } from "./dictionary-dialogs";
    56→import { useDictionaries, useDeleteDictionary, useDownloadDictionary, useResetDictionary } from "@/hooks/use-analysis";
    57→import type { DictionaryType, Dictionary } from "@/types";
    58→import { DICTIONARY_CATEGORY_MAP } from "@/types";
    59→import { toast } from "sonner";
    60→
    61→interface DictionaryListProps {
    62→  type: DictionaryType;
    63→}
    64→
    65→export function DictionaryList({ type }: DictionaryListProps) {
    66→  const [isEditMode, setIsEditMode] = useState(false);
    67→  const [selectedRows, setSelectedRows] = useState<string[]>([]);
    68→  const [addDialogOpen, setAddDialogOpen] = useState(false);
    69→  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
    70→  const [editDialogOpen, setEditDialogOpen] = useState(false);
    71→  const [editingItem, setEditingItem] = useState<Dictionary | null>(null);
    72→  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    73→  const [resetDialogOpen, setResetDialogOpen] = useState(false);
    74→
    75→  // Search state
    76→  const [searchValue, setSearchValue] = useState("");
    77→  const [searchField, setSearchField] = useState<'all' | 'keyword' | 'value'>('all');
    78→  const [wordMatch, setWordMatch] = useState(false);
    79→  const [page, setPage] = useState(1);
    80→  const [pageSize] = useState(20);
    81→
    82→  // Active search (only updates on Enter or button click)
    83→  const [activeSearch, setActiveSearch] = useState("");
    84→
    85→  const category = DICTIONARY_CATEGORY_MAP[type];
    86→
    87→  // API hooks
    88→  const { data, isLoading, isError, refetch } = useDictionaries({
    89→    type,
    90→    page,
    91→    pageSize,
    92→    search: activeSearch || undefined,
    93→    searchField,
    94→    wordMatch,
    95→  });
    96→
    97→  const deleteMutation = useDeleteDictionary();
    98→  const downloadMutation = useDownloadDictionary(type);
    99→  const resetMutation = useResetDictionary();
   100→
   101→  const items = data?.items || [];
   102→  const total = data?.total || 0;
   103→  const totalPages = data?.totalPages || 1;
   104→
   105→  const handleSearch = () => {
   106→    setPage(1);
   107→    setActiveSearch(searchValue);
   108→  };
   109→
   110→  const handleKeyDown = (e: React.KeyboardEvent) => {
   111→    if (e.key === 'Enter') {
   112→      handleSearch();
   113→    }
   114→  };
   115→
   116→  const toggleSelectAll = (checked: boolean) => {
   117→    if (checked) {
   118→      setSelectedRows(items.map((row) => row.id));
   119→    } else {
   120→      setSelectedRows([]);
   121→    }
   122→  };
   123→
   124→  const toggleSelectRow = (id: string, checked: boolean) => {
   125→    if (checked) {
   126→      setSelectedRows((prev) => [...prev, id]);
   127→    } else {
   128→      setSelectedRows((prev) => prev.filter((rowId) => rowId !== id));
   129→    }
   130→  };
   131→
   132→  const handleEdit = (item: Dictionary) => {
   133→    setEditingItem(item);
   134→    setEditDialogOpen(true);
   135→  };
   136→
   137→  const handleDeleteSelected = async () => {
   138→    try {
   139→      await deleteMutation.mutateAsync({ type, ids: selectedRows });
   140→      setSelectedRows([]);
   141→      setDeleteDialogOpen(false);
   142→      toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
   143→    } catch (error) {
   144→      toast.error('삭제 중 오류가 발생했습니다.');
   145→    }
   146→  };
   147→
   148→  const handleDownload = async () => {
   149→    try {
   150→      const blob = await downloadMutation.mutateAsync();
   151→      const url = window.URL.createObjectURL(blob);
   152→      const a = document.createElement('a');
   153→      a.href = url;
   154→      a.download = `${type.toLowerCase()}_dictionary.csv`;
   155→      document.body.appendChild(a);
   156→      a.click();
   157→      window.URL.revokeObjectURL(url);
   158→      document.body.removeChild(a);
   159→      toast.success('다운로드가 시작되었습니다.');
   160→    } catch (error) {
   161→      toast.error('다운로드 중 오류가 발생했습니다.');
   162→    }
   163→  };
   164→
   165→  const handleReset = async () => {
   166→    try {
   167→      await resetMutation.mutateAsync(type);
   168→      setResetDialogOpen(false);
   169→      toast.success('사전이 초기화되었습니다.');
   170→    } catch (error) {
   171→      toast.error('초기화 중 오류가 발생했습니다.');
   172→    }
   173→  };
   174→
   175→  // Determine if this is a SYNONYM type to show direction
   176→  const isSynonymType = category === 'SYNONYM';
   177→  const isSetType = category === 'SET';
   178→  const isMapType = category === 'MAP';
   179→
   180→  // Get direction from dictionary item (bidirectional if keyword is null)
   181→  const getDirection = (item: Dictionary) => {
   182→    return item.keyword === null ? 'bidirectional' : 'unidirectional';
   183→  };
   184→
   185→  // Render value as badges
   186→  const renderValueBadges = (value: string) => {
   187→    const parts = value.split(',').map(v => v.trim()).filter(Boolean);
   188→    return (
   189→      <div className="flex flex-wrap gap-1">
   190→        {parts.map((part, i) => (
   191→          <Badge key={i} variant="secondary" className="text-xs font-normal">
   192→            {part}
   193→          </Badge>
   194→        ))}
   195→      </div>
   196→    );
   197→  };
   198→
   199→  return (
   200→    <div className="space-y-4">
   201→      {/* Toolbar */}
   202→      <div className="flex flex-wrap items-center justify-between gap-4 bg-card p-4 border rounded-lg">
   203→        <div className="flex items-center gap-2">
   204→          <Select value={searchField} onValueChange={(v) => setSearchField(v as 'all' | 'keyword' | 'value')}>
   205→            <SelectTrigger className="w-[120px]">
   206→              <SelectValue placeholder="필터" />
   207→            </SelectTrigger>
   208→            <SelectContent>
   209→              <SelectItem value="all">전체</SelectItem>
   210→              {!isSetType && <SelectItem value="keyword">Keyword</SelectItem>}
   211→              <SelectItem value="value">{isSetType ? '단어' : 'Value'}</SelectItem>
   212→            </SelectContent>
   213→          </Select>
   214→          <div className="relative">
   215→            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
   216→            <Input
   217→              placeholder="검색어 입력 (Enter)"
   218→              className="pl-9 w-[200px]"
   219→              value={searchValue}
   220→              onChange={(e) => setSearchValue(e.target.value)}
   221→              onKeyDown={handleKeyDown}
   222→            />
   223→          </div>
   224→          <div className="flex items-center space-x-2">
   225→            <Checkbox
   226→              id="word-match"
   227→              checked={wordMatch}
   228→              onCheckedChange={(checked) => setWordMatch(!!checked)}
   229→            />
   230→            <label htmlFor="word-match" className="text-sm font-medium">
   231→              단어매칭
   232→            </label>
   233→          </div>
   234→        </div>
   235→
   236→        <div className="flex items-center gap-2">
   237→          {!isEditMode ? (
   238→            <Button
   239→              variant="outline"
   240→              size="sm"
   241→              onClick={handleDownload}
   242→              disabled={downloadMutation.isPending}
   243→            >
   244→              {downloadMutation.isPending ? (
   245→                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
   246→              ) : (
   247→                <Download className="mr-2 h-4 w-4" />
   248→              )}
   249→              Download
   250→            </Button>
   251→          ) : (
   252→            <>
   253→              <Button size="sm" onClick={() => setAddDialogOpen(true)}>
   254→                <Plus className="mr-2 h-4 w-4" />
   255→                추가
   256→              </Button>
   257→              <Button
   258→                variant="destructive"
   259→                size="sm"
   260→                disabled={selectedRows.length === 0}
   261→                onClick={() => setDeleteDialogOpen(true)}
   262→              >
   263→                <Trash2 className="mr-2 h-4 w-4" />
   264→                삭제 ({selectedRows.length})
   265→              </Button>
   266→              <DropdownMenu>
   267→                <DropdownMenuTrigger asChild>
   268→                  <Button variant="outline" size="sm">
   269→                    <MoreVertical className="mr-2 h-4 w-4" />
   270→                    더보기
   271→                  </Button>
   272→                </DropdownMenuTrigger>
   273→                <DropdownMenuContent>
   274→                  <DropdownMenuItem onClick={() => setUploadDialogOpen(true)}>
   275→                    <Upload className="mr-2 h-4 w-4" />
   276→                    파일 업로드
   277→                  </DropdownMenuItem>
   278→                  <DropdownMenuSeparator />
   279→                  <DropdownMenuItem
   280→                    className="text-destructive"
   281→                    onClick={() => setResetDialogOpen(true)}
   282→                  >
   283→                    사전 초기화
   284→                  </DropdownMenuItem>
   285→                </DropdownMenuContent>
   286→              </DropdownMenu>
   287→            </>
   288→          )}
   289→          <Button
   290→            variant="outline"
   291→            size="sm"
   292→            onClick={() => refetch()}
   293→            disabled={isLoading}
   294→          >
   295→            <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
   296→          </Button>
   297→          <Button
   298→            variant={isEditMode ? "secondary" : "outline"}
   299→            size="sm"
   300→            onClick={() => {
   301→              setIsEditMode(!isEditMode);
   302→              setSelectedRows([]);
   303→            }}
   304→          >
   305→            {isEditMode ? (
   306→              <><Eye className="mr-2 h-4 w-4" />보기</>
   307→            ) : (
   308→              <><Pencil className="mr-2 h-4 w-4" />수정</>
   309→            )}
   310→          </Button>
   311→        </div>
   312→      </div>
   313→
   314→      {/* Table */}
   315→      <div className="rounded-md border bg-background">
   316→        {isLoading ? (
   317→          <div className="flex items-center justify-center h-64">
   318→            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
   319→          </div>
   320→        ) : isError ? (
   321→          <div className="flex flex-col items-center justify-center h-64 text-muted-foreground">
   322→            <AlertCircle className="h-8 w-8 mb-2" />
   323→            <p>데이터를 불러오는데 실패했습니다.</p>
   324→            <Button variant="link" onClick={() => refetch()}>다시 시도</Button>
   325→          </div>
   326→        ) : (
   327→          <Table>
   328→            <TableHeader>
   329→              <TableRow>
   330→                {isEditMode && (
   331→                  <TableHead className="w-[50px]">
   332→                    <Checkbox
   333→                      checked={selectedRows.length === items.length && items.length > 0}
   334→                      onCheckedChange={(checked) => toggleSelectAll(!!checked)}
   335→                    />
   336→                  </TableHead>
   337→                )}
   338→
   339→                {/* SET Type: Just "단어" column */}
   340→                {isSetType && (
   341→                  <>
   342→                    <TableHead>단어</TableHead>
   343→                    <TableHead className="w-[150px]">등록일</TableHead>
   344→                  </>
   345→                )}
   346→
   347→                {/* SYNONYM Type: Direction, Representative, Synonyms */}
   348→                {isSynonymType && (
   349→                  <>
   350→                    <TableHead className="w-[60px]">방향</TableHead>
   351→                    <TableHead className="w-[150px]">대표어</TableHead>
   352→                    <TableHead>동의어</TableHead>
   353→                    <TableHead className="w-[120px]">등록일</TableHead>
   354→                  </>
   355→                )}
   356→
   357→                {/* MAP Type: Original, Arrow, Result */}
   358→                {isMapType && (
   359→                  <>
   360→                    <TableHead className="w-[200px]">
   361→                      {type === 'SPACE' ? '붙여쓴 말' : '복합어'}
   362→                    </TableHead>
   363→                    <TableHead className="w-[40px]"></TableHead>
   364→                    <TableHead>
   365→                      {type === 'SPACE' ? '분리 결과' : '분해 결과'}
   366→                    </TableHead>
   367→                    <TableHead className="w-[120px]">등록일</TableHead>
   368→                  </>
   369→                )}
   370→
   371→                {isEditMode && <TableHead className="text-right w-[100px]">액션</TableHead>}
   372→              </TableRow>
   373→            </TableHeader>
   374→            <TableBody>
   375→              {items.length === 0 ? (
   376→                <TableRow>
   377→                  <TableCell
   378→                    colSpan={isEditMode ? 5 : 4}
   379→                    className="text-center text-muted-foreground h-32"
   380→                  >
   381→                    등록된 데이터가 없습니다.
   382→                  </TableCell>
   383→                </TableRow>
   384→              ) : items.map((item) => (
   385→                <TableRow key={item.id}>
   386→                  {isEditMode && (
   387→                    <TableCell>
   388→                      <Checkbox
   389→                        checked={selectedRows.includes(item.id)}
   390→                        onCheckedChange={(checked) => toggleSelectRow(item.id, !!checked)}
   391→                      />
   392→                    </TableCell>
   393→                  )}
   394→
   395→                  {/* SET Type Cells - SET types store word in keyword field */}
   396→                  {isSetType && (
   397→                    <>
   398→                      <TableCell className="font-medium">{item.keyword || item.value}</TableCell>
   399→                      <TableCell className="text-muted-foreground text-sm">
   400→                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
   401→                      </TableCell>
   402→                    </>
   403→                  )}
   404→
   405→                  {/* SYNONYM Type Cells */}
   406→                  {isSynonymType && (
   407→                    <>
   408→                      <TableCell>
   409→                        {getDirection(item) === 'bidirectional' ? (
   410→                          <ArrowLeftRight className="h-4 w-4 text-blue-500" />
   411→                        ) : (
   412→                          <ArrowRight className="h-4 w-4 text-green-500" />
   413→                        )}
   414→                      </TableCell>
   415→                      <TableCell className="font-medium">
   416→                        {item.keyword || <span className="text-muted-foreground">-</span>}
   417→                      </TableCell>
   418→                      <TableCell>{renderValueBadges(item.value)}</TableCell>
   419→                      <TableCell className="text-muted-foreground text-sm">
   420→                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
   421→                      </TableCell>
   422→                    </>
   423→                  )}
   424→
   425→                  {/* MAP Type Cells */}
   426→                  {isMapType && (
   427→                    <>
   428→                      <TableCell className="font-medium">{item.keyword}</TableCell>
   429→                      <TableCell>
   430→                        <ArrowRight className="h-4 w-4 text-muted-foreground" />
   431→                      </TableCell>
   432→                      <TableCell>{renderValueBadges(item.value)}</TableCell>
   433→                      <TableCell className="text-muted-foreground text-sm">
   434→                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
   435→                      </TableCell>
   436→                    </>
   437→                  )}
   438→
   439→                  {isEditMode && (
   440→                    <TableCell className="text-right">
   441→                      <Button
   442→                        variant="ghost"
   443→                        size="sm"
   444→                        onClick={() => handleEdit(item)}
   445→                      >
   446→                        수정
   447→                      </Button>
   448→                    </TableCell>
   449→                  )}
   450→                </TableRow>
   451→              ))}
   452→            </TableBody>
   453→          </Table>
   454→        )}
   455→      </div>
   456→
   457→      {/* Pagination */}
   458→      <div className="flex items-center justify-between">
   459→        <div className="text-sm text-muted-foreground">
   460→          총 {total.toLocaleString()}건 중 {((page - 1) * pageSize) + 1} - {Math.min(page * pageSize, total)}
   461→        </div>
   462→        <div className="flex items-center gap-2">
   463→          <Button
   464→            variant="outline"
   465→            size="sm"
   466→            disabled={page <= 1}
   467→            onClick={() => setPage(p => p - 1)}
   468→          >
   469→            이전
   470→          </Button>
   471→          <span className="text-sm px-2">
   472→            {page} / {totalPages}
   473→          </span>
   474→          <Button
   475→            variant="outline"
   476→            size="sm"
   477→            disabled={page >= totalPages}
   478→            onClick={() => setPage(p => p + 1)}
   479→          >
   480→            다음
   481→          </Button>
   482→        </div>
   483→      </div>
   484→
   485→      {/* Dialogs */}
   486→      <AddDictionaryDialog
   487→        open={addDialogOpen}
   488→        onOpenChange={setAddDialogOpen}
   489→        type={type}
   490→      />
   491→
   492→      <EditDictionaryDialog
   493→        open={editDialogOpen}
   494→        onOpenChange={setEditDialogOpen}
   495→        type={type}
   496→        item={editingItem}
   497→      />
   498→
   499→      <FileUploadDialog
   500→        open={uploadDialogOpen}
   501→        onOpenChange={setUploadDialogOpen}
   502→        type={type}
   503→      />
   504→
   505→      {/* Delete Confirmation */}
   506→      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
   507→        <AlertDialogContent>
   508→          <AlertDialogHeader>
   509→            <AlertDialogTitle>삭제 확인</AlertDialogTitle>
   510→            <AlertDialogDescription>
   511→              선택한 {selectedRows.length}개 항목을 삭제하시겠습니까?
   512→              이 작업은 되돌릴 수 없습니다.
   513→            </AlertDialogDescription>
   514→          </AlertDialogHeader>
   515→          <AlertDialogFooter>
   516→            <AlertDialogCancel>취소</AlertDialogCancel>
   517→            <AlertDialogAction
   518→              onClick={handleDeleteSelected}
   519→              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
   520→            >
   521→              {deleteMutation.isPending ? (
   522→                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
   523→              ) : null}
   524→              삭제
   525→            </AlertDialogAction>
   526→          </AlertDialogFooter>
   527→        </AlertDialogContent>
   528→      </AlertDialog>
   529→
   530→      {/* Reset Confirmation */}
   531→      <AlertDialog open={resetDialogOpen} onOpenChange={setResetDialogOpen}>
   532→        <AlertDialogContent>
   533→          <AlertDialogHeader>
   534→            <AlertDialogTitle>사전 초기화</AlertDialogTitle>
   535→            <AlertDialogDescription>
   536→              모든 데이터가 삭제됩니다. 정말 초기화하시겠습니까?
   537→              이 작업은 되돌릴 수 없습니다.
   538→            </AlertDialogDescription>
   539→          </AlertDialogHeader>
   540→          <AlertDialogFooter>
   541→            <AlertDialogCancel>취소</AlertDialogCancel>
   542→            <AlertDialogAction
   543→              onClick={handleReset}
   544→              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
   545→            >
   546→              {resetMutation.isPending ? (
   547→                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
   548→              ) : null}
   549→              초기화
   550→            </AlertDialogAction>
   551→          </AlertDialogFooter>
   552→        </AlertDialogContent>
   553→      </AlertDialog>
   554→    </div>
   555→  );
   556→}
