     1→'use client';
     2→
     3→import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
     4→import apiClient from '@/lib/api/client';
     5→import { mapDictionaryListResponse, mapPagedDictionaryResponse } from '@/lib/api/dictionary-mapper';
     6→import type {
     7→  Dictionary,
     8→  DictionaryType,
     9→  DictionarySummaryItem,
    10→  DictionaryCompileStatus,
    11→  AnalysisResult,
    12→  PaginatedResponse,
    13→  DictionaryWithId,
    14→  CompileResult,
    15→  BackendPagedResponse,
    16→} from '@/types';
    17→
    18→// ========================================
    19→// Query Keys
    20→// ========================================
    21→
    22→export const analysisKeys = {
    23→  all: ['analysis'] as const,
    24→  dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
    25→  dictionaryList: (type: DictionaryType, page?: number, search?: string) =>
    26→    [...analysisKeys.dictionaries(), type, { page, search }] as const,
    27→  dictionarySearch: (type: DictionaryType, word: string) =>
    28→    [...analysisKeys.dictionaries(), 'search', type, word] as const,
    29→  dictionarySummary: () => [...analysisKeys.all, 'dictionary-summary'] as const,
    30→  compileStatus: () => [...analysisKeys.all, 'compile-status'] as const,
    31→  analyzeTest: () => [...analysisKeys.all, 'analyze-test'] as const,
    32→};
    33→
    34→// ========================================
    35→// Dictionary List Hooks
    36→// ========================================
    37→
    38→interface DictionaryListParams {
    39→  type: DictionaryType;
    40→  page?: number;
    41→  pageSize?: number;
    42→  search?: string;
    43→  searchField?: 'all' | 'keyword' | 'value';
    44→  wordMatch?: boolean;
    45→}
    46→
    47→export function useDictionaries(params: DictionaryListParams) {
    48→  const { type, page = 1, pageSize = 20, search, wordMatch = false } = params;
    49→
    50→  return useQuery({
    51→    queryKey: analysisKeys.dictionaryList(type, page, search),
    52→    queryFn: async (): Promise<PaginatedResponse<Dictionary>> => {
    53→      // If search is provided, use search endpoint (returns array)
    54→      if (search && search.trim()) {
    55→        const response = await apiClient.get<DictionaryWithId[]>(
    56→          `/api/v1/dictionary/${type}/search`,
    57→          {
    58→            params: {
    59→              word: search,
    60→              isMatch: wordMatch,
    61→            },
    62→          }
    63→        );
    64→        return mapDictionaryListResponse(response.data, page, pageSize);
    65→      }
    66→
    67→      // Regular list endpoint with pagination - returns PagedResponse
    68→      const response = await apiClient.get<BackendPagedResponse>(
    69→        `/api/v1/dictionary/${type}`,
    70→        {
    71→          params: {
    72→            page: page - 1, // Backend uses 0-based pagination
    73→            size: pageSize,
    74→          },
    75→        }
    76→      );
    77→      return mapPagedDictionaryResponse(response.data, page, pageSize);
    78→    },
    79→    staleTime: 30000, // 30 seconds
    80→  });
    81→}
    82→
    83→// ========================================
    84→// Dictionary CRUD Hooks
    85→// ========================================
    86→
    87→interface CreateDictionaryParams {
    88→  type: DictionaryType;
    89→  keyword?: string | null;
    90→  value?: string | null;
    91→}
    92→
    93→export function useCreateDictionary() {
    94→  const queryClient = useQueryClient();
    95→
    96→  return useMutation({
    97→    mutationFn: async (params: CreateDictionaryParams) => {
    98→      const response = await apiClient.post(
    99→        '/api/v1/dictionary',
   100→        {
   101→          keyword: params.keyword,
   102→          type: params.type,
   103→          value: params.value,
   104→        }
   105→      );
   106→      return response.data;
   107→    },
   108→    onSuccess: (_, variables) => {
   109→      queryClient.invalidateQueries({
   110→        queryKey: analysisKeys.dictionaryList(variables.type),
   111→      });
   112→      queryClient.invalidateQueries({
   113→        queryKey: analysisKeys.dictionarySummary(),
   114→      });
   115→    },
   116→  });
   117→}
   118→
   119→interface UpdateDictionaryParams {
   120→  type: DictionaryType;
   121→  id: string;
   122→  keyword?: string | null;
   123→  value?: string | null;
   124→}
   125→
   126→export function useUpdateDictionary() {
   127→  const queryClient = useQueryClient();
   128→
   129→  return useMutation({
   130→    mutationFn: async (params: UpdateDictionaryParams) => {
   131→      const response = await apiClient.put(
   132→        `/api/v1/dictionary/${params.id}`,
   133→        {
   134→          keyword: params.keyword ?? '',
   135→          type: params.type,
   136→          value: params.value,
   137→        }
   138→      );
   139→      return response.data;
   140→    },
   141→    onSuccess: (_, variables) => {
   142→      queryClient.invalidateQueries({
   143→        queryKey: analysisKeys.dictionaryList(variables.type),
   144→      });
   145→      queryClient.invalidateQueries({
   146→        queryKey: analysisKeys.dictionarySummary(),
   147→      });
   148→    },
   149→  });
   150→}
   151→
   152→interface DeleteDictionaryParams {
   153→  type: DictionaryType;
   154→  ids: string[];
   155→}
   156→
   157→export function useDeleteDictionary() {
   158→  const queryClient = useQueryClient();
   159→
   160→  return useMutation({
   161→    mutationFn: async (params: DeleteDictionaryParams) => {
   162→      // Backend only supports single delete, so we delete in parallel
   163→      await Promise.all(
   164→        params.ids.map(id =>
   165→          apiClient.delete(`/api/v1/dictionary/${id}`)
   166→        )
   167→      );
   168→    },
   169→    onSuccess: (_, variables) => {
   170→      queryClient.invalidateQueries({
   171→        queryKey: analysisKeys.dictionaryList(variables.type),
   172→      });
   173→      queryClient.invalidateQueries({
   174→        queryKey: analysisKeys.dictionarySummary(),
   175→      });
   176→    },
   177→  });
   178→}
   179→
   180→// ========================================
   181→// Bulk Operations (Unsupported - return errors)
   182→// ========================================
   183→
   184→interface BulkUploadParams {
   185→  type: DictionaryType;
   186→  file: File;
   187→  overwrite: boolean;
   188→}
   189→
   190→export function useBulkUpload() {
   191→  const queryClient = useQueryClient();
   192→
   193→  return useMutation({
   194→    mutationFn: async (_params: BulkUploadParams) => {
   195→      throw new Error('Bulk upload is not supported by current backend');
   196→    },
   197→    onSuccess: (_, variables) => {
   198→      queryClient.invalidateQueries({
   199→        queryKey: analysisKeys.dictionaryList(variables.type),
   200→      });
   201→      queryClient.invalidateQueries({
   202→        queryKey: analysisKeys.dictionarySummary(),
   203→      });
   204→    },
   205→  });
   206→}
   207→
   208→export function useDownloadDictionary(_type: DictionaryType) {
   209→  return useMutation({
   210→    mutationFn: async () => {
   211→      throw new Error('Download is not supported by current backend');
   212→    },
   213→  });
   214→}
   215→
   216→export function useResetDictionary() {
   217→  const queryClient = useQueryClient();
   218→
   219→  return useMutation({
   220→    mutationFn: async (_type: DictionaryType) => {
   221→      throw new Error('Reset is not supported by current backend');
   222→    },
   223→    onSuccess: (_, type) => {
   224→      queryClient.invalidateQueries({
   225→        queryKey: analysisKeys.dictionaryList(type),
   226→      });
   227→      queryClient.invalidateQueries({
   228→        queryKey: analysisKeys.dictionarySummary(),
   229→      });
   230→    },
   231→  });
   232→}
