'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import { mapDictionaryListResponse, mapPagedDictionaryResponse } from '@/lib/api/dictionary-mapper';
import type {
  Dictionary,
  DictionaryType,
  DictionarySummaryItem,
  DictionaryCompileStatus,
  AnalysisResult,
  PaginatedResponse,
  DictionaryWithId,
  CompileResult,
  BackendPagedResponse,
} from '@/types';

// ========================================
// Query Keys
// ========================================

export const analysisKeys = {
  all: ['analysis'] as const,
  dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
  dictionaryList: (type: DictionaryType, page?: number, search?: string) =>
    [...analysisKeys.dictionaries(), type, { page, search }] as const,
  dictionarySearch: (type: DictionaryType, word: string) =>
    [...analysisKeys.dictionaries(), 'search', type, word] as const,
  dictionarySummary: () => [...analysisKeys.all, 'dictionary-summary'] as const,
  compileStatus: () => [...analysisKeys.all, 'compile-status'] as const,
  analyzeTest: () => [...analysisKeys.all, 'analyze-test'] as const,
};

// ========================================
// Dictionary List Hooks
// ========================================

interface DictionaryListParams {
  type: DictionaryType;
  page?: number;
  pageSize?: number;
  search?: string;
  searchField?: 'all' | 'keyword' | 'value';
  wordMatch?: boolean;
}

export function useDictionaries(params: DictionaryListParams) {
  const { type, page = 1, pageSize = 20, search, wordMatch = false } = params;

  return useQuery({
    queryKey: analysisKeys.dictionaryList(type, page, search),
    queryFn: async (): Promise<PaginatedResponse<Dictionary>> => {
      // If search is provided, use search endpoint (returns array)
      if (search && search.trim()) {
        const response = await apiClient.get<DictionaryWithId[]>(
          `/api/v1/dictionary/${type}/search`,
          {
            params: {
              word: search,
              isMatch: wordMatch,
            },
          }
        );
        return mapDictionaryListResponse(response.data, page, pageSize);
      }

      // Regular list endpoint with pagination - returns PagedResponse
      const response = await apiClient.get<BackendPagedResponse>(
        `/api/v1/dictionary/${type}`,
        {
          params: {
            page: page - 1, // Backend uses 0-based pagination
            size: pageSize,
          },
        }
      );
      return mapPagedDictionaryResponse(response.data, page, pageSize);
    },
    staleTime: 30000, // 30 seconds
  });
}

// ========================================
// Dictionary CRUD Hooks
// ========================================

interface CreateDictionaryParams {
  type: DictionaryType;
  keyword?: string | null;
  value?: string | null;
}

export function useCreateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: CreateDictionaryParams) => {
      const response = await apiClient.post(
        '/api/v1/dictionary',
        {
          keyword: params.keyword,
          type: params.type,
          value: params.value,
        }
      );
      return response.data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

interface UpdateDictionaryParams {
  type: DictionaryType;
  id: string;
  keyword?: string | null;
  value?: string | null;
}

export function useUpdateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: UpdateDictionaryParams) => {
      const response = await apiClient.put(
        `/api/v1/dictionary/${params.id}`,
        {
          keyword: params.keyword ?? '',
          type: params.type,
          value: params.value,
        }
      );
      return response.data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

interface DeleteDictionaryParams {
  type: DictionaryType;
  ids: string[];
}

export function useDeleteDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: DeleteDictionaryParams) => {
      // Backend only supports single delete, so we delete in parallel
      await Promise.all(
        params.ids.map(id =>
          apiClient.delete(`/api/v1/dictionary/${id}`)
        )
      );
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

// ========================================
// Bulk Operations (Unsupported - return errors)
// ========================================

interface BulkUploadParams {
  type: DictionaryType;
  file: File;
  overwrite: boolean;
}

export function useBulkUpload() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (_params: BulkUploadParams) => {
      throw new Error('Bulk upload is not supported by current backend');
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

export function useDownloadDictionary(_type: DictionaryType) {
  return useMutation({
    mutationFn: async () => {
      throw new Error('Download is not supported by current backend');
    },
  });
}

export function useResetDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (_type: DictionaryType) => {
      throw new Error('Reset is not supported by current backend');
    },
    onSuccess: (_, type) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(type),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

// ========================================
// Summary & Compile Status (Unsupported - return empty)
// ========================================

export function useDictionarySummary() {
  return useQuery({
    queryKey: analysisKeys.dictionarySummary(),
    queryFn: async (): Promise<DictionarySummaryItem[]> => {
      // Backend doesn't support summary endpoint, return empty array
      return [];
    },
    staleTime: Infinity, // Don't refetch since it's always empty
  });
}

export function useCompileStatus() {
  return useQuery({
    queryKey: analysisKeys.compileStatus(),
    queryFn: async (): Promise<DictionaryCompileStatus[]> => {
      // Backend doesn't support compile status endpoint, return empty array
      return [];
    },
    staleTime: Infinity,
  });
}

interface CompileDictionaryParams {
  types: DictionaryType[];
}

export function useCompileDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: CompileDictionaryParams): Promise<CompileResult[]> => {
      if (params.types.length === 0) {
        // Compile all
        const response = await apiClient.post<CompileResult[]>(
          '/api/v1/dictionary/compile'
        );
        return response.data;
      }

      // Compile specific types in parallel
      const results = await Promise.all(
        params.types.map(async (type) => {
          const response = await apiClient.post<CompileResult>(
            `/api/v1/dictionary/compile/${type}`
          );
          return response.data;
        })
      );
      return results;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.compileStatus(),
      });
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionarySummary(),
      });
    },
  });
}

// ========================================
// Analysis Test
// ========================================

interface AnalyzeTextParams {
  text: string;
  analyzer?: string;
  index?: string;
  dictionaryTypes?: DictionaryType[];
}

export function useAnalyzeText() {
  return useMutation({
    mutationFn: async (params: AnalyzeTextParams) => {
      const response = await apiClient.post<AnalysisResult>(
        '/_dsearch/analysis/test',
        params
      );
      return response.data;
    },
  });
}

interface DetailAnalyzeParams {
  index: string;
  query: string;
  keyword: string;
}

export function useDetailAnalyze() {
  return useMutation({
    mutationFn: async (params: DetailAnalyzeParams) => {
      const queryWithKeyword = params.query.replace(/\$keyword/g, params.keyword);
      const response = await apiClient.post(
        `/${params.index}/_search`,
        JSON.parse(queryWithKeyword)
      );
      return response.data;
    },
  });
}

// ========================================
// Synonym Search (Reference)
// ========================================

interface SynonymSearchParams {
  keyword: string;
}

interface SynonymSearchResult {
  system: Array<{ posTag: string; prob: number }>;
  user: Array<{ name: string; keyword: string; value: string }>;
}

export function useSynonymSearch() {
  return useMutation({
    mutationFn: async (params: SynonymSearchParams) => {
      const response = await apiClient.get<SynonymSearchResult>(
        '/_dsearch/dictionary/search',
        {
          params: { keyword: params.keyword },
        }
      );
      return response.data;
    },
  });
}

import type { Dictionary, DictionaryWithId, PaginatedResponse, BackendPagedResponse } from '@/types';

/**
 * Transform backend DictionaryWithId response to frontend Dictionary model
 */
export function mapDictionaryResponse(data: DictionaryWithId): Dictionary {
  return {
    id: data.id,
    type: data.dictionary.type,
    keyword: data.dictionary.keyword,
    value: data.dictionary.value ?? '',
    createdAt: data.dictionary.createdTime,
    updatedAt: data.dictionary.updatedTime,
  };
}

/**
 * Transform backend PagedResponse to frontend PaginatedResponse
 * Uses the total count from backend for accurate pagination
 */
export function mapPagedDictionaryResponse(
  data: BackendPagedResponse,
  requestedPage: number,
  pageSize: number
): PaginatedResponse<Dictionary> {
  return {
    items: data.items.map(mapDictionaryResponse),
    total: data.total,
    page: requestedPage,
    pageSize,
    totalPages: data.totalPages,
  };
}

/**
 * Transform array of backend responses to paginated frontend response
 * Used for search results that return arrays without pagination metadata
 */
export function mapDictionaryListResponse(
  data: DictionaryWithId[],
  page: number,
  pageSize: number
): PaginatedResponse<Dictionary> {
  return {
    items: data.map(mapDictionaryResponse),
    total: data.length,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(data.length / pageSize)),
  };
}

