import type { CollectionHistory as HistoryType } from "@/types";

interface CollectionHistoryProps {
  collectionId: string;
}

const PAGE_SIZE = 10;

type HistoryTypeFilter = "ALL" | "FULL_INDEX" | "EXPOSE" | "AUTO";

const TYPE_OPTIONS: { value: HistoryTypeFilter; label: string }[] = [
  { value: "ALL", label: "All Types" },
  { value: "FULL_INDEX", label: "Full Index" },
  { value: "EXPOSE", label: "Expose" },
  { value: "AUTO", label: "Auto" },
];

function getStatusBadgeVariant(
  status: HistoryType["status"]
): "default" | "secondary" | "destructive" | "outline" {
  switch (status) {
    case "SUCCESS":
      return "default";
    case "RUNNING":
      return "secondary";
    case "FAILED":
      return "destructive";
    case "CANCELLED":
      return "outline";
    default:
      return "outline";
  }
}

function getTypeBadgeVariant(
  type: HistoryType["type"]
): "default" | "secondary" | "outline" {
  switch (type) {
    case "FULL_INDEX":
      return "default";
    case "EXPOSE":
      return "secondary";
    case "AUTO":
      return "outline";
    default:
      return "outline";
  }
}

export function CollectionHistory({ collectionId }: CollectionHistoryProps) {
  const [page, setPage] = useState(1);
  const [typeFilter, setTypeFilter] = useState<HistoryTypeFilter>("ALL");
  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);

  const {
    data: historyData,
    isLoading,
    refetch,
    isRefetching,
  } = useCollectionHistory(collectionId, {
    page,
    pageSize: PAGE_SIZE,
    type: typeFilter === "ALL" ? undefined : typeFilter,
  });

  const deleteHistory = useDeleteCollectionHistory();

  const handleDelete = async () => {
    if (!deleteTarget) return;

    try {
      await deleteHistory.mutateAsync({
        collectionId,
        historyId: deleteTarget,
      });
      toast.success("History entry deleted");
      setDeleteTarget(null);
    } catch (error) {
      toast.error("Failed to delete history entry");
      console.error(error);
    }
  };

  const handleTypeFilterChange = (value: HistoryTypeFilter) => {
    setTypeFilter(value);
    setPage(1);
  };

