'use client';

import { useState, useMemo } from 'react';
import { Plus, Pencil, Trash2, Search, Eye, FileText } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import Editor from '@monaco-editor/react';
import {
  useIndexDocuments,
  useIndexedTerms,
  useCreateDocument,
  useUpdateDocument,
  useDeleteDocument,
} from '@/hooks/use-indices';
import { IndexMappings } from '@/types';
import { toast } from 'sonner';

type DataMode = 'source' | 'indexed';
type PageSize = 5 | 10 | 20;

interface DataViewProps {
  indexName: string;
  mappings?: IndexMappings;
}

export function DataView({ indexName, mappings }: DataViewProps) {
  const [mode, setMode] = useState<DataMode>('source');
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState<PageSize>(10);

  // Source mode states
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [selectedDoc, setSelectedDoc] = useState<{
    _id: string;
    _source: Record<string, unknown>;
  } | null>(null);
  const [newDocValue, setNewDocValue] = useState('{\n  \n}');
  const [editDocValue, setEditDocValue] = useState('');

  // Indexed mode states
  const [searchKeyword, setSearchKeyword] = useState('');
  const [selectedField, setSelectedField] = useState('');
  const [selectedDocId, setSelectedDocId] = useState('');

  const {
    data: documentsData,
    isLoading: isDocumentsLoading,
    refetch: refetchDocuments,
  } = useIndexDocuments(indexName, page, pageSize);

  const { data: termVectors, isLoading: isTermsLoading } = useIndexedTerms(
    indexName,
    selectedDocId,
    selectedField
  );

  const createDocument = useCreateDocument();
  const updateDocument = useUpdateDocument();
  const deleteDocument = useDeleteDocument();

  // Get field names from mappings
  const fieldNames = useMemo(() => {
    if (!mappings?.properties) return [];
    const extractFields = (
      props: Record<string, unknown>,
      prefix = ''
    ): string[] => {
      const fields: string[] = [];
      for (const [key, value] of Object.entries(props)) {
        const fullKey = prefix ? `${prefix}.${key}` : key;
        const prop = value as { type?: string; properties?: Record<string, unknown> };
        if (prop.type && prop.type !== 'object' && prop.type !== 'nested') {
          fields.push(fullKey);
        }
        if (prop.properties) {
          fields.push(...extractFields(prop.properties, fullKey));
        }
      }
      return fields;
    };
    return extractFields(mappings.properties);
  }, [mappings]);

  // Dynamic columns from first document
  const columns = useMemo(() => {
    if (!documentsData?.hits?.length) return [];
    const firstDoc = documentsData.hits[0]._source;
    return Object.keys(firstDoc).slice(0, 6); // Limit to first 6 columns
